  "c17092736.lua":"--古代の遠眼鏡\n--Ancient Telescope\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--confirm\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetType(EFFECT_TYPE_ACTIVATE)\n\te1:SetCode(EVENT_FREE_CHAIN)\n\te1:SetTarget(s.cftg)\n\te1:SetOperation(s.cfop)\n\tc:RegisterEffect(e1)\nend\nfunction s.cftg(e,tp,eg,ep,ev,re,r,rp,chk)\n\tif chk==0 then return Duel.GetFieldGroupCount(tp,0,LOCATION_DECK)>0 end\n\tDuel.SetTargetPlayer(tp)\nend\nfunction s.cfop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal p=Duel.GetChainInfo(0,CHAININFO_TARGET_PLAYER)\n\tlocal ct=math.min(5,Duel.GetFieldGroupCount(p,0,LOCATION_DECK))\n\tif ct==0 then return end\n\tDuel.Hint(HINT_SELECTMSG,p,HINTMSG_CONFIRM)\n\tlocal ac=Duel.AnnounceLevel(p,1,ct)\n\tlocal g=Duel.GetDecktopGroup(1-p,ac)\n\tif #g>0 then\n\t\tDuel.ConfirmCards(p,g)\n\tend\nend",
  "official/c17185260.lua":"--インフェルノ・ハンマー\n--Inferno Hammer\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--pos\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetDescription(aux.Stringid(id,0))\n\te1:SetCategory(CATEGORY_POSITION+CATEGORY_SET)\n\te1:SetProperty(EFFECT_FLAG_CARD_TARGET)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_TRIGGER_O)\n\te1:SetCode(EVENT_BATTLE_DESTROYING)\n\te1:SetCondition(aux.bdogcon)\n\te1:SetTarget(s.postg)\n\te1:SetOperation(s.posop)\n\tc:RegisterEffect(e1)\nend\nfunction s.filter(c)\n\treturn c:IsFaceup() and c:IsCanTurnSet()\nend\nfunction s.postg(e,tp,eg,ep,ev,re,r,rp,chk,chkc)\n\tif chkc then return chkc:IsLocation(LOCATION_MZONE) and chkc:IsControler(1-tp) and s.filter(chkc) end\n\tif chk==0 then return Duel.IsExistingTarget(s.filter,tp,0,LOCATION_MZONE,1,nil) end\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_FACEUP)\n\tlocal g=Duel.SelectTarget(tp,s.filter,tp,0,LOCATION_MZONE,1,1,nil)\n\tDuel.SetOperationInfo(0,CATEGORY_POSITION,g,1,tp,POS_FACEDOWN_DEFENSE)\nend\nfunction s.posop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal tc=Duel.GetFirstTarget()\n\tif tc and tc:IsRelateToEffect(e) and tc:IsFaceup() then\n\t\tDuel.ChangePosition(tc,POS_FACEDOWN_DEFENSE)\n\tend\nend",
  "c17185260.lua":"--インフェルノ・ハンマー\n--Inferno Hammer\nlocal s,id=GetID()\nfunction s.initial_effect(c)\n\t--pos\n\tlocal e1=Effect.CreateEffect(c)\n\te1:SetDescription(aux.Stringid(id,0))\n\te1:SetCategory(CATEGORY_POSITION+CATEGORY_SET)\n\te1:SetProperty(EFFECT_FLAG_CARD_TARGET)\n\te1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_TRIGGER_O)\n\te1:SetCode(EVENT_BATTLE_DESTROYING)\n\te1:SetCondition(aux.bdogcon)\n\te1:SetTarget(s.postg)\n\te1:SetOperation(s.posop)\n\tc:RegisterEffect(e1)\nend\nfunction s.filter(c)\n\treturn c:IsFaceup() and c:IsCanTurnSet()\nend\nfunction s.postg(e,tp,eg,ep,ev,re,r,rp,chk,chkc)\n\tif chkc then return chkc:IsLocation(LOCATION_MZONE) and chkc:IsControler(1-tp) and s.filter(chkc) end\n\tif chk==0 then return Duel.IsExistingTarget(s.filter,tp,0,LOCATION_MZONE,1,nil) end\n\tDuel.Hint(HINT_SELECTMSG,tp,HINTMSG_FACEUP)\n\tlocal g=Duel.SelectTarget(tp,s.filter,tp,0,LOCATION_MZONE,1,1,nil)\n\tDuel.SetOperationInfo(0,CATEGORY_POSITION,g,1,tp,POS_FACEDOWN_DEFENSE)\nend\nfunction s.posop(e,tp,eg,ep,ev,re,r,rp)\n\tlocal tc=Duel.GetFirstTarget()\n\tif tc and tc:IsRelateToEffect(e) and tc:IsFaceup() then\n\t\tDuel.ChangePosition(tc,POS_FACEDOWN_DEFENSE)\n\tend\nend",
